73:   NAPI_STATUS_THROWS(napi_get_value_string_utf8(env, val, NULL, 0, &name##_size)) \
74:   char* name = new char[name##_size + 1];                               \
75:   NAPI_STATUS_THROWS(napi_get_value_string_utf8(env, val, name, name##_size + 1, &name##_size)) \
76:   name[name##_size] = '\0';
77: 
78: #define NAPI_ARGV_UTF8_NEW(name, i) \
79:   NAPI_UTF8_NEW(name, argv[i])
80: 
81: // TODO: consider using encoding options instead of type checking
82: #define LD_STRING_OR_BUFFER_TO_COPY(env, from, to)                      \
83:   char* to##Ch_ = 0;                                                    \
84:   size_t to##Sz_ = 0;                                                   \
85:   if (IsString(env, from)) {                                            \
86:     napi_get_value_string_utf8(env, from, NULL, 0, &to##Sz_);           \
87:     to##Ch_ = new char[to##Sz_ + 1];                                    \
88:     napi_get_value_string_utf8(env, from, to##Ch_, to##Sz_ + 1, &to##Sz_); \
89:     to##Ch_[to##Sz_] = '\0';                                            \
90:   } else if (IsBuffer(env, from)) {                                     \
91:     char* buf = 0;                                                      \
92:     napi_get_buffer_info(env, from, (void **)&buf, &to##Sz_);           \
93:     to##Ch_ = new char[to##Sz_];                                        \
94:     memcpy(to##Ch_, buf, to##Sz_);                                      \
95:   } else {                                                              \
96:     char* buf = 0;                                                      \
97:     napi_typedarray_type type;                                          \
98:     napi_status status = napi_get_typedarray_info(env, from, &type, &to##Sz_, (void **)&buf, NULL, NULL); \
99:     if (status != napi_ok || type != napi_typedarray_type::napi_uint8_array) { \
100:       /* TODO: refactor so that we can napi_throw_type_error() here */  \
101:       to##Sz_ = 0;                                                      \
102:       to##Ch_ = new char[to##Sz_];                                      \
103:     } else {                                                            \
104:       to##Ch_ = new char[to##Sz_];                                      \
105:       memcpy(to##Ch_, buf, to##Sz_);                                    \
106:     }                                                                   \
107:   }
