237: /**
238:  * Returns internal Encoding enum matching the given encoding option.
239:  */
240: static Encoding GetEncoding (napi_env env, napi_value options, const char* option) {
241:   napi_value value;
242:   size_t copied;
243:   char buf[2];
244: 
245:   if (napi_get_named_property(env, options, option, &value) == napi_ok &&
246:     napi_get_value_string_utf8(env, value, buf, 2, &copied) == napi_ok && copied == 1) {
247:     // Value is either "buffer", "utf8" or "view" so we only have to read the first char
248:     switch (buf[0]) {
249:       case 'b': return Encoding::buffer;
250:       case 'v': return Encoding::view;
251:     }
252:   }
253: 
254:   return Encoding::utf8;
255: }
256: 
257: /**
258:  * Returns internal Encoding enum by its equivalent numeric value.
259:  */
260: static Encoding GetEncoding (napi_env env, napi_value value) {
261:   int32_t result;
262: 
263:   if (napi_get_value_int32(env, value, &result) == napi_ok) {
264:     return static_cast<Encoding>(result);
265:   }
266: 
267:   return Encoding::utf8;
268: }
