306: static std::string StringProperty (napi_env env, napi_value obj, const char* key) {
307:   if (HasProperty(env, obj, key)) {
308:     napi_value value = GetProperty(env, obj, key);
309:     if (IsString(env, value)) {
310:       size_t size = 0;
311:       napi_get_value_string_utf8(env, value, NULL, 0, &size);
312: 
313:       char* buf = new char[size + 1];
314:       napi_get_value_string_utf8(env, value, buf, size + 1, &size);
315:       buf[size] = '\0';
316: 
317:       std::string result = buf;
318:       delete [] buf;
319:       return result;
320:     }
321:   }
322: 
323:   return "";
