355: /**
356:  * Converts an array containing Buffer or string keys to a vector.
357:  */
358: static std::vector<std::string> KeyArray (napi_env env, napi_value arr) {
359:   uint32_t length;
360:   std::vector<std::string> result;
361: 
362:   if (napi_get_array_length(env, arr, &length) == napi_ok) {
363:     result.reserve(length);
364: 
365:     for (uint32_t i = 0; i < length; i++) {
366:       napi_value element;
367: 
368:       if (napi_get_element(env, arr, i, &element) == napi_ok) {
369:         LD_STRING_OR_BUFFER_TO_COPY(env, element, to);
370:         result.emplace_back(toCh_, toSz_);
371:         delete [] toCh_;
372:       }
373:     }
374:   }
375: 
376:   return result;
377: }
