396: /**
397:  * Helper struct for caching and converting a key-value pair to napi_values.
398:  */
399: struct Entry {
400:   Entry (const leveldb::Slice& key, const leveldb::Slice& value)
401:     : key_(key.data(), key.size()),
402:       value_(value.data(), value.size()) {}
403: 
404:   void ConvertByMode (napi_env env, Mode mode, const Encoding keyEncoding, const Encoding valueEncoding, napi_value& result) const {
405:     if (mode == Mode::entries) {
406:       napi_create_array_with_length(env, 2, &result);
407: 
408:       napi_value keyElement;
409:       napi_value valueElement;
410: 
411:       Convert(env, &key_, keyEncoding, keyElement);
412:       Convert(env, &value_, valueEncoding, valueElement);
413: 
414:       napi_set_element(env, result, 0, keyElement);
415:       napi_set_element(env, result, 1, valueElement);
416:     } else if (mode == Mode::keys) {
417:       Convert(env, &key_, keyEncoding, result);
418:     } else {
419:       Convert(env, &value_, valueEncoding, result);
420:     }
421:   }
422: 
423:   static void Convert (napi_env env, const std::string* s, const Encoding encoding, napi_value& result) {
424:     if (s == NULL) {
425:       napi_get_undefined(env, &result);
426:     } else if (encoding == Encoding::buffer || encoding == Encoding::view) {
427:       napi_create_buffer_copy(env, s->size(), s->data(), NULL, &result);
428:     } else {
429:       napi_create_string_utf8(env, s->data(), s->size(), &result);
430:     }
431:   }
432: 
433: private:
434:   std::string key_;
435:   std::string value_;
436: };
