565: /**
566:  * Owns the LevelDB storage, cache, filter policy and resources.
567:  */
568: struct Database {
569:   Database ()
570:     : db_(NULL),
571:       sharedBuffer_(NULL),
572:       blockCache_(NULL),
573:       filterPolicy_(leveldb::NewBloomFilterPolicy(10)),
574:       resourceSequence_(0),
575:       pendingCloseWorker_(NULL),
576:       ref_(NULL),
577:       sharedBufferRef_(NULL),
578:       priorityWork_(0) {}
579: 
580:   ~Database () {
581:     if (db_ != NULL) {
582:       threadsafe_close(*this);
583:     }
584:   }
585: 
586:   leveldb::Status Open (const leveldb::Options& options,
587:                         const std::string &location,
588:                         bool multithreading) {
589:     location_ = location;
590:     return threadsafe_open(options, multithreading, *this);
591:   }
592: 
593:   void CloseDatabase () {
594:     if (db_ != NULL) {
595:       threadsafe_close(*this);
596:     }
597:     if (blockCache_) {
598:       delete blockCache_;
599:       blockCache_ = NULL;
600:     }
601:   }
602: 
603:   leveldb::Status Put (const leveldb::WriteOptions& options,
604:                        leveldb::Slice key,
605:                        leveldb::Slice value) {
606:     return db_->Put(options, key, value);
607:   }
608: 
609:   leveldb::Status Get (const leveldb::ReadOptions& options,
610:                        leveldb::Slice key,
611:                        leveldb::ValueSink& value) {
612:     return db_->Get(options, key, &value);
613:   }
614: 
615:   leveldb::Status Del (const leveldb::WriteOptions& options,
616:                        leveldb::Slice key) {
617:     return db_->Delete(options, key);
618:   }
619: 
620:   leveldb::Status WriteBatch (const leveldb::WriteOptions& options,
621:                               leveldb::WriteBatch* batch) {
622:     return db_->Write(options, batch);
623:   }
624: 
625:   uint64_t ApproximateSize (const leveldb::Range* range) {
626:     uint64_t size = 0;
627:     db_->GetApproximateSizes(range, 1, &size);
628:     return size;
629:   }
630: 
631:   void CompactRange (const leveldb::Slice* start,
632:                      const leveldb::Slice* end) {
633:     db_->CompactRange(start, end);
634:   }
635: 
636:   void GetProperty (const leveldb::Slice& property, std::string* value) {
637:     db_->GetProperty(property, value);
638:   }
639: 
640:   const leveldb::Snapshot* NewSnapshot () {
641:     return db_->GetSnapshot();
642:   }
643: 
644:   leveldb::Iterator* NewIterator (leveldb::ReadOptions* options) {
645:     return db_->NewIterator(*options);
646:   }
647: 
648:   void ReleaseSnapshot (const leveldb::Snapshot* snapshot) {
649:     return db_->ReleaseSnapshot(snapshot);
650:   }
651: 
652:   // The env argument is unused but reminds us to increment priorityWork_
653:   // only in the JavaScript main thread to avoid needing a lock around
654:   // that and pendingCloseWorker_.
655:   void IncrementPriorityWork (napi_env env) {
656:     priorityWork_++;
657:   }
658: 
659:   void DecrementPriorityWork (napi_env env) {
660:     if (--priorityWork_ == 0 && pendingCloseWorker_ != NULL) {
661:       pendingCloseWorker_->Queue(env);
662:       pendingCloseWorker_ = NULL;
663:     }
664:   }
665: 
666:   bool HasPriorityWork () const {
667:     return priorityWork_ > 0;
668:   }
669: 
670:   bool SetSharedBuffer (napi_env env, napi_value value) {
671:     // Delete reference to previous buffer if any
672:     if (sharedBufferRef_) {
673:       napi_delete_reference(env, sharedBufferRef_);
674:       sharedBufferRef_ = NULL;
675:     }
676: 
677:     // Get underlying data (length is separately communicated, on use)
678:     if (napi_get_buffer_info(env, value, (void**)&sharedBuffer_, NULL) != napi_ok) {
679:       sharedBuffer_ = NULL;
680:       return false;
681:     }
682: 
683:     // Create reference in order to keep buffer alive
684:     if (napi_create_reference(env, value, 1, &sharedBufferRef_) != napi_ok) {
685:       sharedBufferRef_ = NULL;
686:       return false;
687:     }
688: 
689:     return true;
690:   }
691: 
692:   void ReleaseReferences (napi_env env) {
693:     if (ref_ != NULL) napi_reference_unref(env, ref_, NULL);
694:     if (sharedBufferRef_ != NULL) napi_reference_unref(env, sharedBufferRef_, NULL);
695:   }
696: 
697:   void DeleteReferences (napi_env env) {
698:     if (ref_ != NULL) napi_delete_reference(env, ref_);
699:     if (sharedBufferRef_ != NULL) napi_delete_reference(env, sharedBufferRef_);
700:   }
701: 
702:   leveldb::DB* db_;
703:   char* sharedBuffer_;
704:   leveldb::Cache* blockCache_;
705:   const leveldb::FilterPolicy* filterPolicy_;
706:   uint32_t resourceSequence_;
707:   BaseWorker *pendingCloseWorker_;
708:   std::map<uint32_t, Resource*> resources_;
709:   napi_ref ref_;
710: 
711: private:
712:   napi_ref sharedBufferRef_;
713:   std::atomic<uint32_t> priorityWork_;
714:   std::string location_;
715: 
716:   // for separation of concerns the threadsafe functionality was kept at the global
717:   // level and made a friend so it is explict where the threadsafe boundary exists
718:   friend leveldb::Status threadsafe_open(const leveldb::Options &options,
719:                                          bool multithreading,
720:                                          Database &db_instance);
721:   friend leveldb::Status threadsafe_close(Database &db_instance);
722: };
