774: /**
775:  * Represents an object that has a strong reference until explicitly closed. In
776:  * addition, resources are tracked in database->resources in order to close
777:  * them when the Node.js environment is tore down.
778:  */
779: struct Resource {
780:   Resource (Database* database)
781:     : database(database),
782:       id_(++database->resourceSequence_),
783:       ref_(NULL) {
784:   }
785: 
786:   virtual ~Resource () { }
787:   virtual void CloseResource () = 0;
788: 
789:   void Attach (napi_env env, napi_value context) {
790:     napi_create_reference(env, context, 1, &ref_);
791:     database->resources_[id_] = this;
792:   }
793: 
794:   void Detach (napi_env env) {
795:     database->resources_.erase(id_);
796:     if (ref_ != NULL) napi_delete_reference(env, ref_);
797:   }
798: 
799:   static void CollectGarbage (napi_env env, void* data, void* hint) {
800:     if (data) {
801:       delete (Resource*)data;
802:     }
803:   }
804: 
805:   Database* database;
806: 
807: private:
808:   const uint32_t id_;
809:   napi_ref ref_;
810: };
