845: /**
846:  * Owns a leveldb iterator.
847:  */
848: struct BaseIterator {
849:   BaseIterator(Database* database,
850:                const bool reverse,
851:                std::string* lt,
852:                std::string* lte,
853:                std::string* gt,
854:                std::string* gte,
855:                const int limit,
856:                const bool fillCache,
857:                ExplicitSnapshot* snapshot)
858:     : database_(database),
859:       hasClosed_(false),
860:       didSeek_(false),
861:       reverse_(reverse),
862:       lt_(lt),
863:       lte_(lte),
864:       gt_(gt),
865:       gte_(gte),
866:       limit_(limit),
867:       count_(0) {
868:     options_ = new leveldb::ReadOptions();
869:     options_->fill_cache = fillCache;
870: 
871:     if (snapshot == NULL) {
872:       implicitSnapshot_ = database_->NewSnapshot();
873:       options_->snapshot = implicitSnapshot_;
874:     } else {
875:       implicitSnapshot_ = NULL;
876:       options_->snapshot = snapshot->nut;
877:     }
878: 
879:     dbIterator_ = database_->NewIterator(options_);
880:   }
881: 
882:   virtual ~BaseIterator () {
883:     assert(hasClosed_);
884: 
885:     if (lt_ != NULL) delete lt_;
886:     if (gt_ != NULL) delete gt_;
887:     if (lte_ != NULL) delete lte_;
888:     if (gte_ != NULL) delete gte_;
889: 
890:     delete options_;
891:   }
892: 
893:   bool DidSeek () const {
894:     return didSeek_;
895:   }
896: 
897:   /**
898:    * Seek to the first relevant key based on range options.
899:    */
900:   void SeekToRange () {
901:     didSeek_ = true;
902: 
903:     if (!reverse_ && gte_ != NULL) {
904:       dbIterator_->Seek(*gte_);
905:     } else if (!reverse_ && gt_ != NULL) {
906:       dbIterator_->Seek(*gt_);
907: 
908:       if (dbIterator_->Valid() && dbIterator_->key().compare(*gt_) == 0) {
909:         dbIterator_->Next();
910:       }
911:     } else if (reverse_ && lte_ != NULL) {
912:       dbIterator_->Seek(*lte_);
913: 
914:       if (!dbIterator_->Valid()) {
915:         dbIterator_->SeekToLast();
916:       } else if (dbIterator_->key().compare(*lte_) > 0) {
917:         dbIterator_->Prev();
918:       }
919:     } else if (reverse_ && lt_ != NULL) {
920:       dbIterator_->Seek(*lt_);
921: 
922:       if (!dbIterator_->Valid()) {
923:         dbIterator_->SeekToLast();
924:       } else if (dbIterator_->key().compare(*lt_) >= 0) {
925:         dbIterator_->Prev();
926:       }
927:     } else if (reverse_) {
928:       dbIterator_->SeekToLast();
929:     } else {
930:       dbIterator_->SeekToFirst();
931:     }
932:   }
933: 
934:   /**
935:    * Seek manually (during iteration).
936:    */
937:   void Seek (leveldb::Slice& target) {
938:     didSeek_ = true;
939: 
940:     if (OutOfRange(target)) {
941:       return SeekToEnd();
942:     }
943: 
944:     dbIterator_->Seek(target);
945: 
946:     if (dbIterator_->Valid()) {
947:       int cmp = dbIterator_->key().compare(target);
948:       if (reverse_ ? cmp > 0 : cmp < 0) {
949:         Next();
950:       }
951:     } else { // TODO: can we skip this code path if not in reverse?
952:       SeekToFirst();
953:       if (dbIterator_->Valid()) {
954:         int cmp = dbIterator_->key().compare(target);
955:         if (reverse_ ? cmp > 0 : cmp < 0) {
956:           SeekToEnd();
957:         }
958:       }
959:     }
960:   }
961: 
962:   /**
963:    * Seek to an exact key.
964:    */
965:   bool SeekExact (leveldb::Slice& target) {
966:     didSeek_ = true;
967:     dbIterator_->Seek(target);
968:     return dbIterator_->Valid() && dbIterator_->key() == target;
969:   }
970: 
971:   void CloseIterator () {
972:     if (!hasClosed_) {
973:       hasClosed_ = true;
974: 
975:       delete dbIterator_;
976:       dbIterator_ = NULL;
977: 
978:       if (implicitSnapshot_) {
979:         database_->ReleaseSnapshot(implicitSnapshot_);
980:       }
981:     }
982:   }
983: 
984:   bool Valid () const {
985:     return dbIterator_->Valid() && !OutOfRange(dbIterator_->key());
986:   }
987: 
988:   bool Increment () {
989:     return limit_ < 0 || ++count_ <= limit_;
990:   }
991: 
992:   void Next () {
993:     if (reverse_) dbIterator_->Prev();
994:     else dbIterator_->Next();
995:   }
996: 
997:   void SeekToFirst () {
998:     if (reverse_) dbIterator_->SeekToLast();
999:     else dbIterator_->SeekToFirst();
1000:   }
1001: 
1002:   void SeekToLast () {
1003:     if (reverse_) dbIterator_->SeekToFirst();
1004:     else dbIterator_->SeekToLast();
1005:   }
1006: 
1007:   void SeekToEnd () {
1008:     SeekToLast();
1009:     Next();
1010:   }
1011: 
1012:   leveldb::Slice CurrentKey () const {
1013:     return dbIterator_->key();
1014:   }
1015: 
1016:   leveldb::Slice CurrentValue () const {
1017:     return dbIterator_->value();
1018:   }
1019: 
1020:   leveldb::Status Status () const {
1021:     return dbIterator_->status();
1022:   }
1023: 
1024:   bool OutOfRange (const leveldb::Slice& target) const {
1025:     // The lte and gte options take precedence over lt and gt respectively
1026:     if (lte_ != NULL) {
1027:       if (target.compare(*lte_) > 0) return true;
1028:     } else if (lt_ != NULL) {
1029:       if (target.compare(*lt_) >= 0) return true;
1030:     }
1031: 
1032:     if (gte_ != NULL) {
1033:       if (target.compare(*gte_) < 0) return true;
1034:     } else if (gt_ != NULL) {
1035:       if (target.compare(*gt_) <= 0) return true;
1036:     }
1037: 
1038:     return false;
1039:   }
1040: 
1041:   Database* database_;
1042:   bool hasClosed_;
1043: 
1044: private:
1045:   leveldb::Iterator* dbIterator_;
1046:   bool didSeek_;
1047:   const bool reverse_;
1048:   std::string* lt_;
1049:   std::string* lte_;
1050:   std::string* gt_;
1051:   std::string* gte_;
1052:   const int limit_;
1053:   int count_;
1054:   leveldb::ReadOptions* options_;
1055:   const leveldb::Snapshot* implicitSnapshot_;
1056: };
