1058: /**
1059:  * Extends BaseIterator for reading it from JS land.
1060:  */
1061: struct Iterator final : public BaseIterator, public Resource {
1062:   Iterator (Database* database,
1063:             const bool reverse,
1064:             const bool keys,
1065:             const bool values,
1066:             const int limit,
1067:             std::string* lt,
1068:             std::string* lte,
1069:             std::string* gt,
1070:             std::string* gte,
1071:             const bool fillCache,
1072:             const Encoding keyEncoding,
1073:             const Encoding valueEncoding,
1074:             const uint32_t highWaterMarkBytes,
1075:             unsigned char* state,
1076:             ExplicitSnapshot* snapshot)
1077:     : BaseIterator(database, reverse, lt, lte, gt, gte, limit, fillCache, snapshot),
1078:       Resource(database),
1079:       keys_(keys),
1080:       values_(values),
1081:       keyEncoding_(keyEncoding),
1082:       valueEncoding_(valueEncoding),
1083:       highWaterMarkBytes_(highWaterMarkBytes),
1084:       first_(true),
1085:       nexting_(false),
1086:       aborted_(false),
1087:       ended_(false),
1088:       state_(state) {
1089:   }
1090: 
1091:   ~Iterator () {}
1092: 
1093:   void CloseResource () override {
1094:     BaseIterator::CloseIterator();
1095:   }
1096: 
1097:   bool ReadMany (uint32_t size) {
1098:     cache_.clear();
1099:     cache_.reserve(size);
1100:     size_t bytesRead = 0;
1101:     leveldb::Slice empty;
1102: 
1103:     while (!aborted_) {
1104:       if (!first_) Next();
1105:       else first_ = false;
1106: 
1107:       if (!Valid() || !Increment()) break;
1108: 
1109:       if (keys_ && values_) {
1110:         leveldb::Slice k = CurrentKey();
1111:         leveldb::Slice v = CurrentValue();
1112:         cache_.emplace_back(k, v);
1113:         bytesRead += k.size() + v.size();
1114:       } else if (keys_) {
1115:         leveldb::Slice k = CurrentKey();
1116:         cache_.emplace_back(k, empty);
1117:         bytesRead += k.size();
1118:       } else if (values_) {
1119:         leveldb::Slice v = CurrentValue();
1120:         cache_.emplace_back(empty, v);
1121:         bytesRead += v.size();
1122:       }
1123: 
1124:       if (bytesRead > highWaterMarkBytes_ || cache_.size() >= size) {
1125:         return true;
1126:       }
1127:     }
1128: 
1129:     ended_ = true;
1130:     return false;
1131:   }
1132: 
1133:   const bool keys_;
1134:   const bool values_;
1135:   const Encoding keyEncoding_;
1136:   const Encoding valueEncoding_;
1137:   const uint32_t highWaterMarkBytes_;
1138:   bool first_;
1139:   bool nexting_;
1140:   std::atomic<bool> aborted_;
1141:   bool ended_;
1142:   unsigned char* state_;
1143:   std::vector<Entry> cache_;
1144: };
