1146: /**
1147:  * Hook for when the environment exits. This hook will be called after
1148:  * already-scheduled napi_async_work items have finished, which gives us
1149:  * the guarantee that no db operations will be in-flight at this time.
1150:  */
1151: static void env_cleanup_hook (void* arg) {
1152:   Database* database = (Database*)arg;
1153: 
1154:   // Do everything that db.close() does but synchronously. We're expecting that GC
1155:   // did not (yet) collect the database because that would be a user mistake (not
1156:   // closing their db) made during the lifetime of the environment. That's different
1157:   // from an environment being torn down (like the main process or a worker thread)
1158:   // where it's our responsibility to clean up. Note also, the following code must
1159:   // be a safe noop if called before db_open() or after db_close().
1160:   if (database && database->db_ != NULL) {
1161:     for (const auto& kv : database->resources_) {
1162:       kv.second->CloseResource();
1163:     }
1164: 
1165:     database->CloseDatabase();
1166:   }
1167: }
1168: 
1169: /**
1170:  * Runs when a Database is garbage collected.
1171:  */
1172: static void FinalizeDatabase (napi_env env, void* data, void* hint) {
1173:   if (data) {
1174:     Database* database = (Database*)data;
1175:     napi_remove_env_cleanup_hook(env, env_cleanup_hook, database);
1176:     database->DeleteReferences(env);
1177:     delete database;
1178:   }
1179: }
