1181: /**
1182:  * Returns a context object for a database.
1183:  */
1184: NAPI_METHOD(db_init) {
1185:   Database* database = new Database();
1186:   napi_add_env_cleanup_hook(env, env_cleanup_hook, database);
1187: 
1188:   napi_value result;
1189:   NAPI_STATUS_THROWS(napi_create_external(env, database,
1190:                                           FinalizeDatabase,
1191:                                           NULL, &result));
1192: 
1193:   // Prevent GC of database before close()
1194:   NAPI_STATUS_THROWS(napi_create_reference(env, result, 1, &database->ref_));
1195: 
1196:   return result;
1197: }
