    for (size_t i = 0; i != keys_.size(); i++) {
      leveldb::Slice target = leveldb::Slice(keys_[i]);

      if (iterator_->SeekExact(target)) {
        bitset_[i >> 5] |= 1 << (i & 31); // Set bit
