2240: /**
2241:  * Worker class for nexting an iterator.
2242:  */
2243: struct NextWorker final : public BaseWorker {
2244:   NextWorker (napi_env env, Iterator* iterator, uint32_t size, napi_deferred deferred)
2245:     : BaseWorker(env, iterator->database, deferred, "classic_level.iterator.next"),
2246:       iterator_(iterator), size_(size), ok_() {}
2247: 
2248:   ~NextWorker () {}
2249: 
2250:   void DoExecute () override {
2251:     if (!iterator_->DidSeek()) {
2252:       iterator_->SeekToRange();
2253:     }
2254: 
2255:     ok_ = iterator_->ReadMany(size_);
2256: 
2257:     if (!ok_) {
2258:       SetStatus(iterator_->Status());
2259:     }
2260:   }
2261: 
2262:   void HandleOKCallback (napi_env env, napi_deferred deferred) override {
2263:     if (iterator_->aborted_) {
2264:       napi_value err = CreateCodeError(env, "LEVEL_ABORTED", "Operation has been aborted");
2265:       napi_value name;
2266:       napi_create_string_utf8(env, "AbortError", NAPI_AUTO_LENGTH, &name);
2267:       napi_set_named_property(env, err, "name", name);
2268:       napi_reject_deferred(env, deferred, err);
2269:       return;
2270:     }
2271: 
2272:     size_t size = iterator_->cache_.size();
2273:     napi_value jsArray;
2274:     napi_create_array_with_length(env, size, &jsArray);
2275: 
2276:     const Encoding ke = iterator_->keyEncoding_;
2277:     const Encoding ve = iterator_->valueEncoding_;
2278: 
2279:     for (uint32_t idx = 0; idx < size; idx++) {
2280:       napi_value element;
2281:       iterator_->cache_[idx].ConvertByMode(env, Mode::entries, ke, ve, element);
2282:       napi_set_element(env, jsArray, idx, element);
2283:     }
2284: 
2285:     // TODO: use state_ internally too, replacing ended_?
2286:     if (iterator_->ended_) {
2287:       *iterator_->state_ |= STATE_ENDED;
2288:     }
2289: 
2290:     napi_resolve_deferred(env, deferred, jsArray);
2291:   }
2292: 
2293:   void DoFinally (napi_env env) override {
2294:     iterator_->nexting_ = false;
2295:     BaseWorker::DoFinally(env);
2296:   }
2297: 
2298: private:
2299:   Iterator* iterator_;
2300:   uint32_t size_;
2301:   bool ok_;
2302: };
