2335: struct BatchWorker final : public PriorityWorker {
2336:   BatchWorker (napi_env env,
2337:                Database* database,
2338:                napi_deferred deferred,
2339:                leveldb::WriteBatch* batch,
2340:                const bool sync,
2341:                const bool hasData)
2342:     : PriorityWorker(env, database, deferred, "classic_level.batch.do"),
2343:       batch_(batch), hasData_(hasData) {
2344:     options_.sync = sync;
2345:   }
2346: 
2347:   ~BatchWorker () {
2348:     delete batch_;
2349:   }
2350: 
2351:   void DoExecute () override {
2352:     if (hasData_) {
2353:       SetStatus(database_->WriteBatch(options_, batch_));
2354:     }
2355:   }
