2363: /**
2364:  * Does a batch write operation on a database.
2365:  */
2366: NAPI_METHOD(batch_do) {
2367:   NAPI_ARGV(3);
2368:   NAPI_DB_CONTEXT();
2369:   NAPI_PROMISE();
2370: 
2371:   napi_value array = argv[1];
2372:   const bool sync = BooleanProperty(env, argv[2], "sync", false);
2373: 
2374:   uint32_t length;
2375:   napi_get_array_length(env, array, &length);
2376: 
2377:   leveldb::WriteBatch* batch = new leveldb::WriteBatch();
2378:   bool hasData = false;
2379: 
2380:   for (uint32_t i = 0; i < length; i++) {
2381:     napi_value element;
2382:     napi_get_element(env, array, i, &element);
2383: 
2384:     if (!IsObject(env, element)) continue;
2385: 
2386:     std::string type = StringProperty(env, element, "type");
2387: 
2388:     if (type == "del") {
2389:       if (!HasProperty(env, element, "key")) continue;
2390:       leveldb::Slice key = ToSlice(env, GetProperty(env, element, "key"));
2391: 
2392:       batch->Delete(key);
2393:       if (!hasData) hasData = true;
2394: 
2395:       DisposeSliceBuffer(key);
2396:     } else if (type == "put") {
2397:       if (!HasProperty(env, element, "key")) continue;
2398:       if (!HasProperty(env, element, "value")) continue;
2399: 
2400:       leveldb::Slice key = ToSlice(env, GetProperty(env, element, "key"));
2401:       leveldb::Slice value = ToSlice(env, GetProperty(env, element, "value"));
2402: 
2403:       batch->Put(key, value);
2404:       if (!hasData) hasData = true;
2405: 
2406:       DisposeSliceBuffer(key);
2407:       DisposeSliceBuffer(value);
2408:     }
2409:   }
2410: 
2411:   BatchWorker* worker = new BatchWorker(
2412:     env, database, deferred, batch, sync, hasData
2413:   );
2414: 
2415:   worker->Queue(env);
2416:   return promise;
2417: }
2418: 
2419: /**
2420:  * Owns a WriteBatch.
2421:  */
2422: struct Batch {
2423:   Batch (Database* database)
2424:     : database_(database),
2425:       batch_(new leveldb::WriteBatch()),
2426:       hasData_(false) {}
2427: 
2428:   ~Batch () {
2429:     delete batch_;
2430:   }
2431: 
2432:   void Put (leveldb::Slice key, leveldb::Slice value) {
2433:     batch_->Put(key, value);
2434:     hasData_ = true;
2435:   }
2436: 
2437:   void Del (leveldb::Slice key) {
2438:     batch_->Delete(key);
2439:     hasData_ = true;
2440:   }
2441: 
2442:   void Clear () {
2443:     batch_->Clear();
2444:     hasData_ = false;
2445:   }
2446: 
2447:   leveldb::Status Write (bool sync) {
2448:     leveldb::WriteOptions options;
2449:     options.sync = sync;
2450:     return database_->WriteBatch(options, batch_);
2451:   }
2452: 
2453:   Database* database_;
2454:   leveldb::WriteBatch* batch_;
2455:   bool hasData_;
2456: };
